/** Linear interpolation of L/M/S between the two nearest months. */
export function ambilLmsHC(jenisKelamin: JenisKelamin, umurBulan: number): Lms {
  const tabel = HC_LMS[jenisKelamin];
  const bulanBawah = Math.min(Math.floor(umurBulan), 59);
  const bulanAtas = bulanBawah + 1;
  const bawah = tabel[bulanBawah];
  const atas = tabel[bulanAtas];

  if (!bawah || !atas) {
    throw new RangeError(
      `Tabel LMS lingkar kepala tidak tersedia untuk umur ${umurBulan} bulan`,
    );
  }

  const fraksi = Math.max(0, Math.min(1, umurBulan - bulanBawah));
  return {
    l: bawah.l + (atas.l - bawah.l) * fraksi,
    m: bawah.m + (atas.m - bawah.m) * fraksi,
    s: bawah.s + (atas.s - bawah.s) * fraksi,
  };
}

/** WHO z-score formula. */
export function hitungZScoreHC(nilaiCm: number, { l, m, s }: Lms): number {
  const rasio = nilaiCm / m;
  return l === 0 ? Math.log(rasio) / s : (rasio ** l - 1) / (l * s);
}
